import pandas as pd

def clean(df):
    df['species'] = df['species'].str.strip().str.title()
    allowed_species = {'Adelie', 'Chinstrap', 'Gentoo'}
    df['species'] = df['species'].apply(lambda x: x if x in allowed_species else pd.NA)

    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').str.strip()
    df['body_mass_g'] = df['body_mass_g'].astype(float)
    df = df[(df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)]
    return df

def answer(df):
    return {name: total for name, total in df.groupby('species')['body_mass_g'].sum().items()}
